(()=>{
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const launch=document.createElement('button');launch.className='import-launch';launch.textContent='Find & copy imports';launch.type='button';launch.setAttribute('aria-haspopup','dialog');document.body.append(launch);
const dialog=document.createElement('dialog');dialog.className='import-drawer';dialog.setAttribute('aria-labelledby','imports-title');dialog.innerHTML='<div class="import-drawer-head"><h2 id="imports-title">Find your import</h2><button type="button" class="import-close">Close ×</button></div><p>Copy complete codes here, then paste into the matching game import screen. Source workspaces need compilation. Community imports have not been tested in-game.</p><div class="import-filters"><label>Search<input type="search" id="import-search" placeholder="DeathCat, Forest C2, Factory…"></label><label>Category<select id="import-category"><option value="">All categories</option><option>Blueprints</option><option>Challenges</option><option>Power Plant</option><option>Facility AI</option></select></label><label>Progression<select id="import-stage"><option value="">All stages</option><option>Pre-Era</option><option>Pre-Infinity</option><option>Speed</option></select></label><label>Region<select id="import-region"><option value="">All regions</option></select></label></div><p id="import-count" role="status"></p><div id="import-results"></div><p>Scripts credited to d0sboots retain their <a href="/licenses/d0sboots-PerfectTower.txt">Apache 2.0 license</a>. Source links provide author credits and additional documentation.</p>';document.body.append(dialog);
const search=dialog.querySelector('#import-search'),category=dialog.querySelector('#import-category'),stage=dialog.querySelector('#import-stage'),region=dialog.querySelector('#import-region'),results=dialog.querySelector('#import-results'),count=dialog.querySelector('#import-count');let data,loading;
function render(){const words=search.value.toLowerCase().trim().split(/\s+/).filter(Boolean);const found=data.filter(x=>(!category.value||category.value===x.category)&&(!stage.value||stage.value===x.stage)&&(!region.value||region.value===x.region)&&words.every(w=>(x.title+' '+x.note+' '+x.author).toLowerCase().includes(w)));count.textContent=`${found.length} matching imports`;results.innerHTML=found.length?found.map(x=>`<section class="import-result"><span class="tag">${esc(x.category)} · ${esc(x.format)}</span><h3>${esc(x.title)}</h3><p>${esc(x.note)}</p><p>${x.format==='Source workspace'?'Editable workspace JSON; not a game import.':x.category==='Power Plant'?'Paste into Power Plant → Import.':x.category==='Facility AI'?'Paste into Facility AI → Import.':'Paste into Workshop → Blueprint import.'}</p><button type="button" data-copy-id="${x.id}">${x.format==='Source workspace'?'Copy source workspace':'Copy import code'}</button> <span class="copy-result" role="status"></span><details><summary>View complete code</summary><pre><code>${esc(x.code)}</code></pre></details><a href="${esc(x.source)}" target="_blank" rel="noopener">Source: ${esc(x.author)}</a></section>`).join(''):'<p>No imports match. Try a build name, region or broader search.</p>';}
async function open(query=''){search.value=query;category.value='';stage.value='';region.value='';dialog.showModal();search.focus();count.textContent='Loading imports…';try{if(!loading)loading=fetch('/import-codes.json').then(r=>{if(!r.ok)throw Error();return r.json()}).catch(e=>{loading=null;throw e});data=await loading;if(region.options.length===1)[...new Set(data.map(x=>x.region).filter(Boolean))].sort().forEach(r=>region.add(new Option(r,r)));render()}catch{count.textContent='Imports could not load. Close and reopen to retry.';}}
launch.addEventListener('click',()=>open());dialog.querySelector('.import-close').addEventListener('click',()=>dialog.close());[search,category,stage,region].forEach(el=>el.addEventListener('input',()=>{if(data)render()}));results.addEventListener('click',async e=>{const b=e.target.closest('[data-copy-id]');if(!b)return;const item=data.find(x=>x.id===b.dataset.copyId),status=b.nextElementSibling;try{await navigator.clipboard.writeText(item.code);status.textContent='Copied complete code.'}catch{const d=b.parentElement.querySelector('details');d.open=true;const sel=window.getSelection(),range=document.createRange();range.selectNodeContents(d.querySelector('code'));sel.removeAllRanges();sel.addRange(range);status.textContent='Code selected. Press Ctrl+C or Command+C to copy.';}});
const names=['DeathCat','AllBlue','RpCat','SpookyCat','EveryCat','WaterCat','LazyCat','EarthCat','bluekitties','TrueCat','DeluxeCat','Factory Automation','Simple Skill','Example Miner','Museum Combiner','Adventure Map','Timed Task Looping','Autoclicker','Dust Up-tierer','Button Coordinate Finder','Auto Era Disabler'];
document.querySelectorAll('article a').forEach(a=>{if(!/^https?:/.test(a.getAttribute('href')||''))return;const name=names.find(n=>a.textContent.toLowerCase().includes(n.toLowerCase()));if(name){const b=document.createElement('button');b.type='button';b.className='inline-import';b.textContent='Copy code here';b.setAttribute('aria-label','Find '+name+' import code');b.addEventListener('click',()=>open(name));if(/^Copy /i.test(a.textContent)){a.replaceWith(b)}else a.after(b);}});
document.querySelectorAll('[data-import-query]').forEach(b=>b.addEventListener('click',()=>open(b.dataset.importQuery)));
})();
